const oldSetup=setup;setup=function(){oldSetup();if(state.mistakes.length)return;const form=$('#config');const title=$('.narrow h1');if(title)title.innerHTML=t('Một bài học nhỏ,<br><em>một niềm vui to.</em>','Little lessons.<br><em>Big happy moments.</em>');const presets=document.createElement('section');presets.className='preset-section';presets.innerHTML=`<div class="guide-bubble">${animal(buddy())}<div><b>${t('Mình chọn bài vừa sức nhé!','Let’s find your happy level!')}</b><p>${t('Chọn nhanh bên dưới, hoặc tự chỉnh theo ý em.','Pick a starting point, or make it your own below.')}</p></div></div><div class="preset-grid"><button type="button" data-preset="easy" class="chosen"><span>🌱</span><b>${t('Làm quen','First steps')}</b><small>${t('Cộng trừ · 1 chữ số','Add & subtract · 1 digit')}</small></button><button type="button" data-preset="medium"><span>🌻</span><b>${t('Tự tin','Feeling good')}</b><small>${t('Cộng trừ · 2 chữ số','Add & subtract · 2 digits')}</small></button><button type="button" data-preset="hard"><span>🌳</span><b>${t('Thử thách','Adventure mode')}</b><small>${t('Bốn phép tính','All four operations')}</small></button></div>`;form.before(presets);const formGrid=$('.formgrid');const advanced=document.createElement('details');advanced.className='advanced-settings';advanced.innerHTML=`<summary>${t('Tùy chỉnh bài luyện','Make it your own')} <span>＋</span></summary>`;const firstLabel=form.querySelector('label'),checks=$('.checks');advanced.append(firstLabel,checks,formGrid);form.prepend(advanced);const shortcuts=document.createElement('div');shortcuts.className='quick-settings';shortcuts.innerHTML=`<label>${t('Luyện bao nhiêu câu?','How many questions?')}<div class="chip-row" id="countChips">${[5,10,20].map(n=>`<button type="button" data-count="${n}" class="${n===10?'chosen':''}">${n} ${t('câu','questions')}</button>`).join('')}</div></label><label>${t('Thời gian mỗi câu','Time per question')}<div class="chip-row" id="timeChips">${[10,15,30].map(n=>`<button type="button" data-seconds="${n}" class="${n===15?'chosen':''}">${n}s</button>`).join('')}</div></label>`;form.prepend(shortcuts);form.querySelector('.notice').classList.add('technical-note');const submit=form.querySelector('button[type=submit]');submit.classList.add('wide');$$('[data-count]').forEach(b=>b.onclick=()=>{$('[name=count]').value=b.dataset.count;$$('[data-count]').forEach(x=>x.classList.toggle('chosen',x===b))});$$('[data-seconds]').forEach(b=>b.onclick=()=>{$('[name=seconds]').value=b.dataset.seconds;$$('[data-seconds]').forEach(x=>x.classList.toggle('chosen',x===b))});$$('[data-preset]').forEach(b=>b.onclick=()=>{const kind=b.dataset.preset;$$('[data-preset]').forEach(x=>x.classList.toggle('chosen',x===b));$('[name=type]').value='natural';$('[name=d1]').value=kind==='easy'?1:2;$('[name=d2]').value=kind==='hard'?2:1;$$('[name=op]').forEach(x=>x.checked=kind==='hard'||['+','-'].includes(x.value));$('#quick').value=kind==='easy'?'1':'custom'});$$('[name=op]').forEach(x=>x.checked=['+','-'].includes(x.value))};
let soundEnabled=state.sound!==false,audioContext;function chime(ok){if(!soundEnabled)return;try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();[ok?523:280,ok?659:230,ok?784:200].forEach((f,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain(),at=audioContext.currentTime+i*.09;osc.type='sine';osc.frequency.value=f;gain.gain.setValueAtTime(.045,at);gain.gain.exponentialRampToValueAtTime(.001,at+.18);osc.connect(gain);gain.connect(audioContext.destination);osc.start(at);osc.stop(at+.2)})}catch{}}
const originalAnswer=answerQuiz;answerQuiz=function(ans){const q=session.questions[session.index];chime(ans===q.answer);originalAnswer(ans);$('#feedback')?.setAttribute('role','status')};
const originalShowQuiz=showQuiz;showQuiz=function(){originalShowQuiz();if(view!=='quiz'||session.done)return;const card=$('.narrow .card');if(!card)return;const guide=document.createElement('div');guide.className='quiz-companion';guide.innerHTML=`${animal(buddy())}<span>${t('Cứ từ từ, em làm được mà!','Take your time. You’ve got this!')}</span>`;card.prepend(guide);$$('[data-answer]').forEach((b,i)=>b.classList.add('answer-'+i));$('#clock')?.setAttribute('aria-live','off')};
