const originalGameAnswer=gameAnswer;gameAnswer=function(ans){const q=session.questions[session.index];chime(ans===q.answer);if(ans!==q.answer)q.options=shuffle([...q.options]);originalGameAnswer(ans)};
const originalGameQuestion=gameQuestion;gameQuestion=function(){originalGameQuestion();if(view!=='game'||session.done)return;$('#app').classList.add('game-layout');const h=$('.game-question');h.insertAdjacentHTML('beforebegin',`<div class="game-guide">${animal(buddy())}<span>${t('Vườn thú tính nhẩm','The number garden')}</span></div>`);const accessible=$('[data-access]')?.parentElement;if(accessible){const d=document.createElement('details');d.className='alternative-controls';d.innerHTML=`<summary>${t('Khó nhảy? Chạm đáp án ở đây','Need another way? Tap an answer')}</summary>`;accessible.before(d);d.append(accessible)}};
function hint(q){const [type,op]=q.skill.split(':'),eq=q.explanation;if(type==='fraction')return eq+'\n'+(op==='+'||op==='-'?t('Quy đồng hai mẫu số, cộng hoặc trừ tử số, giữ mẫu số chung rồi rút gọn.','Find a common denominator, add or subtract the numerators, then simplify.'):op==='*'?t('Nhân tử với tử, mẫu với mẫu rồi rút gọn.','Multiply numerators and denominators, then simplify.'):t('Giữ phân số thứ nhất, đảo tử và mẫu phân số thứ hai rồi nhân.','Keep the first fraction, invert the second, then multiply.'));const match=q.q.match(/^(\d+) ([+−×÷]) (\d+)$/);if(match){const a=+match[1],b=+match[3];if(op==='+'&&b>=10){let tens=Math.floor(b/10)*10,ones=b%10;return `${eq}\n${a} + ${tens} = ${a+tens}\n${a+tens} + ${ones} = ${a+b}`};if(op==='-'&&b>=10){let tens=Math.floor(b/10)*10,ones=b%10;return `${eq}\n${a} − ${tens} = ${a-tens}\n${a-tens} − ${ones} = ${a-b}`};if(op==='*'&&b>=10){let tens=Math.floor(b/10)*10,ones=b%10;return `${eq}\n${a} × ${tens} = ${a*tens}\n${a} × ${ones} = ${a*ones}\n${a*tens} + ${a*ones} = ${a*b}`};if(op==='/')return `${eq}\n${b} × ${Math.floor(a/b)} = ${b*Math.floor(a/b)}${a%b?'\n'+a+' − '+b*Math.floor(a/b)+' = '+a%b:''}`;if(op==='*'&&b<=9)return eq+'\n'+Array.from({length:b},()=>a).join(' + ')+' = '+a*b}return eq+'\n'+(op==='+'?t('Tách thành phần nguyên và phần lẻ, rồi cộng từng phần.','Split into whole and fractional parts, then add.'):op==='-'?t('Tìm khoảng cách giữa hai số. Chú ý dấu âm và dấu phẩy.','Find the difference. Watch negative signs and decimal places.'):op==='*'?t('Tách một thừa số thành các phần nhỏ, nhân rồi cộng lại.','Split one factor, multiply each part, then add.'):t('Nhân ngược lại để kiểm tra kết quả.','Multiply back to check the answer.'))}
const zooNav=nav;nav=function(v){zooNav(v);$('#app').classList.toggle('game-layout',view==='game');document.body.dataset.view=view};
function initializeZoo(){document.title='NumiQuest · Vườn thú tính nhẩm';$('.brand').innerHTML=`<span class="brand-mark">${animal('lion')}</span><span class="brand-word">Numi<span>Quest</span><small>${t('VƯỜN THÚ TÍNH NHẨM','A LITTLE MATH ZOO')}</small></span>`;const sound=document.createElement('button');sound.id='soundToggle';sound.className='sound-toggle';sound.setAttribute('aria-label',t('Bật/tắt âm thanh','Toggle sound'));sound.textContent=soundEnabled?'♫':'♪';sound.setAttribute('aria-pressed',soundEnabled);sound.onclick=()=>{soundEnabled=!soundEnabled;state.sound=soundEnabled;save();sound.textContent=soundEnabled?'♫':'♪';sound.setAttribute('aria-pressed',soundEnabled);if(soundEnabled)chime(true)};$('#lang').before(sound);document.body.dataset.view='home';home();translate()}

function drawZooScenery(ctx){ctx.save();ctx.fillStyle='#ffffffbb';for(const [x,y]of [[80,60],[350,35],[570,80]]){ctx.beginPath();ctx.ellipse(x,y,47,15,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(x-5,y-10,22,0,Math.PI*2);ctx.fill()}ctx.strokeStyle='#ab8961';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(48,315);ctx.lineTo(48,150);ctx.moveTo(845,315);ctx.lineTo(845,165);ctx.stroke();ctx.fillStyle='#a1c896';for(const[x,y,r]of [[33,135,42],[68,123,37],[48,100,33],[835,142,37],[866,119,32]]){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawZooPlayer(ctx,x,y){ctx.save();ctx.translate(x,y);let kind=buddy();const circle=(x,y,r,color)=>{ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()};const ellipse=(x,y,rx,ry,color)=>{ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()};ellipse(0,15,20,5,'#4c715533');if(kind==='lion'){circle(0,-1,22,'#bd8b51');circle(-13,-14,7,'#e7b66d');circle(13,-14,7,'#e7b66d');circle(0,-1,16,'#ffda88')}else if(kind==='panda'){circle(-13,-15,8,'#405a4e');circle(13,-15,8,'#405a4e');ellipse(0,0,21,18,'#fff8e5');ellipse(-8,-3,6,8,'#405a4e');ellipse(8,-3,6,8,'#405a4e')}else if(kind==='bunny'){ellipse(-9,-22,6,16,'#fff4e5');ellipse(9,-22,6,16,'#fff4e5');ellipse(-9,-22,2,10,'#e9b4ab');ellipse(9,-22,2,10,'#e9b4ab');ellipse(0,1,20,17,'#fff4e5')}else{ctx.fillStyle='#e5a270';ctx.beginPath();ctx.moveTo(-20,-3);ctx.lineTo(-19,-24);ctx.lineTo(-2,-12);ctx.lineTo(19,-24);ctx.lineTo(20,-3);ctx.fill();ellipse(0,0,21,17,'#e5a270');ellipse(0,7,16,10,'#fff0d3')}circle(-7,-3,2.2,kind==='panda'?'#fff':'#4f5644');circle(7,-3,2.2,kind==='panda'?'#fff':'#4f5644');ellipse(0,4,3,2,'#7b5b45');ctx.strokeStyle='#7b5b45';ctx.lineWidth=1.6;ctx.beginPath();ctx.arc(0,5,5,.2,Math.PI-.2);ctx.stroke();ctx.restore()}
const originalAtlas=atlas;atlas=function(){originalAtlas();const note=$('#app>.notice');if(note){note.className='atlas-welcome';note.innerHTML=`${animal('panda')}<div><b>${t('Bamboo giữ hộ chiếu giúp em nhé!','Bamboo is looking after your passport!')}</b><p>${t('10 điểm đến đang chờ. Chọn một nước rồi thu thập đủ 4 mảnh để mở minh họa địa danh và tìm hiểu châu lục.','10 destinations await. Pick a country and collect 4 pieces to unlock its landmark illustration and discover its continent.')}</p></div>`}const art=$('.landmark');if(art)art.setAttribute('aria-label',t('Minh họa địa danh bằng biểu tượng','Symbolic landmark illustration'))};
const originalReview=startReview;startReview=function(){if(state.gameIntroSeen){originalReview();return}modal(`<div class="intro-animal">${animal(buddy())}</div><h2>${t('Cùng vào vườn thú nhé!','Let’s visit the zoo!')}</h2><div class="instruction-step"><b>1</b><p>${t('Đọc phép tính và tìm đáp án đúng.','Read the question and find the answer.')}</p></div><div class="instruction-step"><b>2</b><p>${t('Dùng trái/phải, rồi nhảy chạm ô đáp án từ bên dưới.','Move left/right, then jump into the answer block from below.')}</p></div><div class="instruction-step"><b>3</b><p>${t('Nhảy hụt được thử lại. Khó điều khiển? Mở nút đáp án bên dưới game.','Missed jumps are fine. Need another way? Open the answer buttons below the game.')}</p></div>`,()=>{state.gameIntroSeen=true;save();originalReview()})};
window.addEventListener('keydown',e=>{if($('#modal').open||e.ctrlKey||e.metaKey||e.altKey||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(view==='quiz'){let i='abcd'.indexOf(e.key.toLowerCase());if(i>=0){const b=$$('[data-answer]')[i];if(b&&!b.disabled){e.preventDefault();b.click()}}else if(e.key==='Enter'&&$('#next')&&!$('#next').hidden){e.preventDefault();$('#next').click()}}});

initializeZoo();
